def nearest_reaching_drone(drones,target):
    answer=-1;best=float('inf')
    for i,(x,y,radius) in enumerate(drones):
        distance=abs(x-target[0])+abs(y-target[1])
        if distance<=radius and distance<best:best=distance;answer=i
    return answer

